import { Request, Response } from 'express';
import { Appointment } from '../models/Appointment';
import { AppError } from '../middleware/errorHandler';
import { logger } from '../utils/logger';
import mongoose from 'mongoose';

interface AuthRequest extends Request {
  user?: {
    userId: string;
    userType: string;
  };
}

// Get all appointments for a doctor
export const getDoctorAppointments = async (req: AuthRequest, res: Response) => {
  try {
    const { userId } = req.user!;
    const appointments = await Appointment.find({ doctorId: userId })
      .populate('patientId', 'name email phone')
      .sort({ date: 1, time: 1 });

    res.json(appointments);
  } catch (error) {
    logger.error('Error fetching doctor appointments:', error);
    throw new AppError('Error fetching appointments', 500);
  }
};

// Get all appointments for a patient
export const getPatientAppointments = async (req: AuthRequest, res: Response) => {
  try {
    const { userId } = req.user!;
    const appointments = await Appointment.find({ patientId: userId })
      .populate('doctorId', 'name specialization')
      .sort({ date: 1, time: 1 });

    res.json(appointments);
  } catch (error) {
    logger.error('Error fetching patient appointments:', error);
    throw new AppError('Error fetching appointments', 500);
  }
};

// Create a new appointment
export const createAppointment = async (req: AuthRequest, res: Response): Promise<Response> => {
  try {
    if (!req.user?.userId) {
      return res.status(401).json({ message: 'Not authenticated' });
    }

    const appointment = new Appointment({
      ...req.body,
      patientId: req.user.userId,
      status: 'scheduled',
    });

    await appointment.save();
    return res.status(201).json(appointment);
  } catch (error) {
    logger.error('Create appointment error:', error);
    if (error instanceof AppError) {
      return res.status(error.statusCode).json({ message: error.message });
    }
    return res.status(500).json({ message: 'Server error' });
  }
};

// Update appointment status
export const updateAppointmentStatus = async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { status } = req.body;

    const appointment = await Appointment.findByIdAndUpdate(
      id,
      { status },
      { new: true }
    );

    if (!appointment) {
      throw new AppError('Appointment not found', 404);
    }

    res.json(appointment);
  } catch (error) {
    logger.error('Error updating appointment status:', error);
    if (error instanceof AppError) {
      throw error;
    }
    throw new AppError('Error updating appointment status', 500);
  }
};

// Get appointment statistics for a doctor
export const getDoctorStats = async (req: AuthRequest, res: Response) => {
  try {
    const { userId } = req.user!;

    const stats = await Appointment.aggregate([
      {
        $match: {
          doctorId: new mongoose.Types.ObjectId(userId),
        },
      },
      {
        $group: {
          _id: null,
          totalAppointments: { $sum: 1 },
          completedAppointments: {
            $sum: { $cond: [{ $eq: ['$status', 'completed'] }, 1, 0] },
          },
          upcomingAppointments: {
            $sum: {
              $cond: [
                {
                  $and: [
                    { $eq: ['$status', 'scheduled'] },
                    { $gte: ['$date', new Date()] },
                  ],
                },
                1,
                0,
              ],
            },
          },
        },
      },
    ]);

    res.json(stats[0] || {
      totalAppointments: 0,
      completedAppointments: 0,
      upcomingAppointments: 0,
    });
  } catch (error) {
    logger.error('Error fetching doctor stats:', error);
    throw new AppError('Error fetching statistics', 500);
  }
};

export const getAppointments = async (req: AuthRequest, res: Response): Promise<Response> => {
  try {
    if (!req.user?.userId) {
      return res.status(401).json({ message: 'Not authenticated' });
    }

    const query = req.user.userType === 'doctor' 
      ? { doctorId: req.user.userId }
      : { patientId: req.user.userId };

    const appointments = await Appointment.find(query)
      .populate('patientId', 'name email')
      .populate('doctorId', 'name email');

    return res.json(appointments);
  } catch (error) {
    logger.error('Get appointments error:', error);
    return res.status(500).json({ message: 'Server error' });
  }
};

export const getAppointmentById = async (req: AuthRequest, res: Response): Promise<Response> => {
  try {
    if (!req.user?.userId) {
      return res.status(401).json({ message: 'Not authenticated' });
    }

    const appointment = await Appointment.findById(req.params.id)
      .populate('patientId', 'name email')
      .populate('doctorId', 'name email');

    if (!appointment) {
      throw new AppError('Appointment not found', 404);
    }

    // Check if user has permission to view this appointment
    if (
      appointment.patientId.toString() !== req.user.userId &&
      appointment.doctorId.toString() !== req.user.userId &&
      req.user.userType !== 'admin'
    ) {
      return res.status(403).json({ message: 'Not authorized to view this appointment' });
    }

    return res.json(appointment);
  } catch (error) {
    logger.error('Get appointment error:', error);
    if (error instanceof AppError) {
      return res.status(error.statusCode).json({ message: error.message });
    }
    return res.status(500).json({ message: 'Server error' });
  }
};

export const updateAppointment = async (req: AuthRequest, res: Response): Promise<Response> => {
  try {
    if (!req.user?.userId) {
      return res.status(401).json({ message: 'Not authenticated' });
    }

    const appointment = await Appointment.findById(req.params.id);
    if (!appointment) {
      throw new AppError('Appointment not found', 404);
    }

    // Check if user has permission to update this appointment
    if (
      appointment.patientId.toString() !== req.user.userId &&
      appointment.doctorId.toString() !== req.user.userId &&
      req.user.userType !== 'admin'
    ) {
      return res.status(403).json({ message: 'Not authorized to update this appointment' });
    }

    const updatedAppointment = await Appointment.findByIdAndUpdate(
      req.params.id,
      { $set: req.body },
      { new: true }
    ).populate('patientId', 'name email').populate('doctorId', 'name email');

    return res.json(updatedAppointment);
  } catch (error) {
    logger.error('Update appointment error:', error);
    if (error instanceof AppError) {
      return res.status(error.statusCode).json({ message: error.message });
    }
    return res.status(500).json({ message: 'Server error' });
  }
};

export const deleteAppointment = async (req: AuthRequest, res: Response): Promise<Response> => {
  try {
    if (!req.user?.userId) {
      return res.status(401).json({ message: 'Not authenticated' });
    }

    const appointment = await Appointment.findById(req.params.id);
    if (!appointment) {
      throw new AppError('Appointment not found', 404);
    }

    // Check if user has permission to delete this appointment
    if (
      appointment.patientId.toString() !== req.user.userId &&
      appointment.doctorId.toString() !== req.user.userId &&
      req.user.userType !== 'admin'
    ) {
      return res.status(403).json({ message: 'Not authorized to delete this appointment' });
    }

    await Appointment.findByIdAndDelete(req.params.id);
    return res.json({ message: 'Appointment deleted successfully' });
  } catch (error) {
    logger.error('Delete appointment error:', error);
    if (error instanceof AppError) {
      return res.status(error.statusCode).json({ message: error.message });
    }
    return res.status(500).json({ message: 'Server error' });
  }
}; 